    return "correct" if r13.is_correct(text) else ("bug" if r13.is_bug(text) else "neither")


def fallback_only(r13, text):
    lo = text.lower()
    return r13.is_correct(text) and not any(p in lo for p in r13.CORRECT_PATTERNS)


